package com.example.jobplatform.worker;
import com.example.jobplatform.config.RabbitConfig; import com.example.jobplatform.dto.JobDtos.JobMessage; import com.example.jobplatform.entity.*; import com.example.jobplatform.repository.JobRepository; import org.springframework.amqp.rabbit.annotation.RabbitListener; import org.springframework.amqp.rabbit.core.RabbitTemplate; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional; import java.time.Instant; import java.util.UUID;
@Component public class JobWorker {
 private final JobRepository jobs;private final RabbitTemplate rabbit;private final int maxAttempts;private final String workerId=System.getenv().getOrDefault("HOSTNAME","local-worker");
 public JobWorker(JobRepository jobs,RabbitTemplate rabbit,@Value("${app.jobs.max-attempts:4}") int maxAttempts){this.jobs=jobs;this.rabbit=rabbit;this.maxAttempts=maxAttempts;}
 @RabbitListener(queues=RabbitConfig.QUEUE) public void consume(JobMessage msg){UUID id=msg.jobId();if(jobs.claim(id)==0)return;Job j=jobs.findById(id).orElse(null);if(j==null)return;try{String result=execute(j.getJobType(),j.getPayload());finish(id,JobStatus.SUCCEEDED,result,null);}catch(Exception ex){fail(id,ex.getMessage());}}
 private String execute(String type,String payload)throws Exception{return switch(type){case "ECHO"->payload;case "UPPERCASE"->payload.toUpperCase();case "SLEEP"->{long ms;try{ms=Long.parseLong(payload);}catch(NumberFormatException e){throw new IllegalArgumentException("SLEEP payload must be milliseconds");}if(ms<0||ms>120000)throw new IllegalArgumentException("SLEEP must be between 0 and 120000 ms");Thread.sleep(ms);yield "Slept for "+ms+" ms";}case "FAIL"->throw new IllegalStateException("Intentional failure requested by FAIL job");default->throw new IllegalArgumentException("Unsupported job type");};}
 @Transactional public void finish(UUID id,JobStatus status,String result,String error){Job j=jobs.findById(id).orElseThrow();j.setStatus(status);j.setResult(result);j.setErrorMessage(error);j.setCompletedAt(Instant.now());j.touch();}
 @Transactional public void fail(UUID id,String error){Job j=jobs.findById(id).orElseThrow();int attempts=j.getAttempts()+1;j.setAttempts(attempts);j.setErrorMessage(error);j.touch();if(attempts<j.getMaxAttempts()){j.setStatus(JobStatus.RETRYING);rabbit.convertAndSend(RabbitConfig.RETRY_EXCHANGE,"retry",new JobMessage(id,j.getPriority()));}else{j.setStatus(JobStatus.DEAD_LETTERED);j.setCompletedAt(Instant.now());rabbit.convertAndSend(RabbitConfig.DLX,"dead",new JobMessage(id,j.getPriority()));}}
}
